.ss-cursor[data-pressed="true"] .ss-cursor__press { transition: transform 80ms ease-out; transform: scale(0.9); }
.ss-cursor__glyph { opacity: 0; grid-area: 1 / 1; transition: transform 0.2s, opacity 0.2s; transform: scale(0); }
.ss-cursor__glyph[data-active="true"] { transform: scale(var(--ss-cursor-size,1)); opacity: 1; }
