.ss-cursor[data-style="circle"][data-kind="ibeam"] .ss-cursor__dot { background: rgba(60, 60, 67, 0.55); border-radius: 2px; width: 4px; height: 20px; margin: -10px 0px 0px -2px; }
.ss-stage[data-theme="dark"] .ss-cursor__dot { background: rgba(255, 255, 255, 0.2); box-shadow: rgba(255, 255, 255, 0.3) 0px 1px 1px inset, rgba(0, 0, 0, 0.3) 0px 2px 10px; }
.ss-cursor[data-style="circle"][data-pressed="true"] .ss-cursor__press { transform: scale(0.8); }
.ss-cursor[data-style="circle"][data-pressed="true"] .ss-cursor__dot { backdrop-filter: none; background: rgba(118, 118, 128, 0.22); }
.ss-stage[data-theme="dark"] .ss-cursor[data-style="circle"][data-pressed="true"] .ss-cursor__dot { background: rgba(255, 255, 255, 0.18); }
.ss-cursor[data-style="circle"][data-pressed="true"] .ss-cursor__dot, .ss-cursor[data-style="circle"][data-kind="grab"] .ss-cursor__dot { background: rgba(118, 118, 128, 0.4); }
.ss-cursor[data-style="touch"] .ss-cursor__dot { backdrop-filter: none; opacity: 0; background: rgba(118, 118, 128, 0.14); width: 34px; height: 34px; margin: -17px 0px 0px -17px; transition: opacity 0.4s, transform 0.45s cubic-bezier(0.22, 1, 0.36, 1); transform: scale(0.7); }
.ss-cursor__streak { transform-origin: 100% center; opacity: 0; pointer-events: none; background: linear-gradient(90deg, rgba(118, 118, 128, 0), rgba(118, 118, 128, 0.16)); border-radius: 13px; width: 0px; height: 26px; transition: opacity 0.16s; position: absolute; top: -13px; left: 0px; }
.ss-cursor[data-swiping] .ss-cursor__streak { opacity: 1; transition: none; }
.ss-cursor[data-style="touch"][data-touching] .ss-cursor__dot { opacity: 1; transition: opacity 0.14s, transform 0.16s cubic-bezier(0.22, 1, 0.36, 1); transform: scale(1); }
.ss-cursor[data-style="touch"][data-pressed="true"] .ss-cursor__dot, .ss-cursor[data-style="touch"][data-swiping] .ss-cursor__dot { background: rgba(118, 118, 128, 0.22); transition: background 80ms, transform 0.1s ease-out; transform: scale(0.82); }
.ss-cursor__glyph svg { filter: drop-shadow(rgba(0, 0, 0, 0.3) 0px 1px 2px); display: block; }
.ss-cursor__arrow path { fill: var(--ss-cursor-ink,#111); stroke: var(--ss-cursor-ink,#111); stroke-width: 2.4px; stroke-linejoin: round; }
.ss-cursor__arrow { filter: drop-shadow(rgba(0, 0, 0, 0.18) 0px 1px 1.5px); display: block; }
.ss-stage[data-theme="dark"] .ss-cursor__arrow, .ss-stage[data-theme="blueprint"] .ss-cursor__arrow { --ss-cursor-ink: #fff; }
.ss-stage[data-theme="dark"] .ss-cursor, .ss-stage[data-theme="blueprint"] .ss-cursor { --ss-cursor-line: #fff; --ss-cursor-edge: #000000bf; }
.ss-stage[data-hit] :is(.ss-cursor, .ss-cursor *) { pointer-events: none !important; }
